function opsAddCase(id,stage,title,goal,terms,principle,example,reading,trap,practice,decision,transfer,video,parts,official=video){
 const index=hubCurriculum.opswork.length;
 const question=(row,offset)=>choiceTask(row[0],row[1],row[2],row[3],index+offset);
 const c={id:'ops-path-'+id,opsStage:stage,section:title.split('：')[0],title,summary:goal,
  body:[principle,reading],related:transfer,diagram:'',source:opsOfficialSources[official],
  examples:[{text:example,meaning:reading}],videoReference:{video,parts},
  tasks:[question(practice,0),question(decision,1)],
  quiz:null,
  reminder:'先读证据，再选择下一步。示例命令用于理解；本课是场景判断，不连接真实服务器。',transfer,
  teachingPages:[
   P('这一课解决什么问题？',[goal,'先读懂示例环境、对象与结果，再完成两步场景判断。不需要真实服务器，也不会修改你的电脑。']),
   {...P('先把术语讲清楚',[], '', '',terms),termsOpen:true},
   P('把关系讲清楚',[principle]),
   P('拆开示例，再读结果',[reading,'以下是教学配置或快照。主机名、用户、路径和版本都需要在实际工作中重新核对。'],example),
   P('常见误解与反例',[trap,decision[3]]),
   P('把判断迁移到工作',[transfer,'作答前：先说明“看到什么”，再说明“还不能证明什么”，最后选择最小范围的验证动作。答对后会给出迁移示例。'])
  ]};
 hubCurriculum.opswork.push(c);
}
Object.assign(beginnerTerms,{
 虚拟机:'用软件模拟的一台独立计算机，有自己的操作系统、虚拟磁盘与网卡。宿主机是实际运行它的电脑；来宾系统是虚拟机里的系统。',
 快照:'保存虚拟机某一时刻状态以便回退的机制，依赖原虚拟磁盘。它不是独立备份，不能替代数据库一致性备份。',
 NAT:'网络地址转换。虚拟机使用私网地址，通过宿主机一侧转换访问外部；不代表外部设备能直接访问虚拟机。',
 SSH:'加密的远程登录协议。客户端要核验服务器主机密钥；成功连上后，权限仍由登录账号与系统策略决定。',
 退出状态:'命令结束时交给 Shell 的数字。通常 0 表示成功，非零表示工具定义的失败或特殊结果；它不是屏幕上的输出文本。',
 幂等:'重复执行同一操作后仍保持相同的目标效果。自动化要描述期望状态，并检查重复执行是否造成额外修改。',
 数据库实例:'运行中的数据库服务及其内存、进程等状态。实例管理数据库对象；客户端连接不等于数据文件本身。',
 主键:'表中用于唯一标识一行的列或列组合，不能为空且不能重复。业务编号与技术主键可以不同。',
 事务:'把一组数据库操作作为一个逻辑工作单元处理。是否能回滚要看语句类别、存储引擎和提交状态。',
 索引:'帮助数据库查找数据的辅助结构，类似有序目录。占用空间并增加写入维护成本，不保证每条查询都会更快。',
 复制:'把数据库变更传递到另一个实例的过程。可能存在延迟，也可能传播误删，不能替代独立备份。',
 镜像:'用于创建容器的分层文件系统与运行配置。镜像通常只读；容器还有自己的可写层。标签可以移动，摘要标识具体内容。',
 数据卷:'Docker 管理的持久化存储对象，生命周期可独立于容器。绑定挂载则把宿主机某个明确路径映射进容器。',
 Compose:'用一个 YAML 文件描述多服务、网络与存储的工具。Compose 运行应用，Dockerfile 则描述如何构建镜像。',
 Pod:'Kubernetes 中最小的可部署工作负载单元，包含一个或多个共享网络等资源的容器。Pod 可以被重建，名字与 IP 不应作为永久入口。',
 Deployment:'Kubernetes 中声明无状态应用副本与更新策略的对象，通过 ReplicaSet 管理 Pod。它不是容器内的进程。',
 Service:'Kubernetes 中给一组后端提供相对稳定网络入口的对象。通常用标签选择 Pod；有入口不等于一定有可用后端。',
 命名空间:'Kubernetes 用于划分命名范围和管理边界的机制。不同命名空间可以有同名对象；它本身不自动提供完整网络隔离。',
 CNI:'容器网络接口规范。Kubernetes 网络插件据此接入 Pod 网络；具体路由与策略行为取决于插件。',
 CoreDNS:'Kubernetes 常用的集群 DNS 组件，帮助 Pod 按服务名解析地址。域名能解析仍不能证明后端应用可用。',
 就绪探针:'判断容器是否适合接收业务流量的检查。失败通常使 Pod 不再作为就绪后端；不等同于存活探针触发重启。',
 触发器:'监控系统中根据指标表达式判断异常的规则。告警通知是后续动作；没有通知不一定代表没有异常。',
 堡垒机:'集中管理远程访问入口、身份、授权与审计的系统。资产登记、访问授权和目标系统账号权限需要分别核对。',
 RPO:'业务能接受的数据丢失时间窗口，例如最多丢失最近 15 分钟数据；它不是恢复耗时。',
 RTO:'业务要求恢复服务的目标时间，例如 1 小时内恢复；要通过演练验证备份、恢复和依赖准备是否满足。'
});
opsAddCase('lab','environment','练习环境：宿主机、虚拟机与快照','先准备可重来的练习环境，再学习系统操作。',
 ['虚拟机','快照','NAT'],
 '你的电脑是宿主机，虚拟机是来宾系统。分配内存和磁盘时要给宿主机留出余量；虚拟磁盘中的文件不等于宿主机同名目录。NAT 常用于来宾系统向外访问，桥接则通常让来宾直接接入所在局域网，是否允许应看网络策略。',
 '宿主机：个人电脑\n来宾：练习 Linux\n网络：NAT；SSH 入口需单独确认\n变更前：关键信息备份 + 测试快照\n回退后：重新核对文件、网卡、时间与服务',
 '先记录来宾 IP、账号、网卡模式和快照时间。快照回退会丢失快照之后的修改；快照依赖磁盘文件，硬盘损坏时未必能恢复。先练习创建普通文件与回退，再进行服务安装。',
 '误区：开了 NAT，公网就能随意登录虚拟机。NAT 的出站能力和外部访问入口是两件事。',
 ['来宾能上网，但同事连不上它，先查什么？','核对网卡模式、来宾地址和入站路径',['立即给来宾 root 密码','删除宿主机所有防火墙规则'],'先确认网络方向，避免为解决入站问题扩大权限。'],
 ['准备试一次配置修改，怎样便于回退？','记录原配置、备份必要数据，再在练习环境试验',['快照能代替全部数据库备份','修改后再决定如何恢复'],'回退准备应发生在变更前，并验证恢复后的状态。'],
 '迁移示例：换成云主机后，没有本地虚拟机快照按钮也要准备数据备份、配置副本和回退步骤。','linux',[4,5,6]);
opsAddCase('versions','environment','版本与连接：先认系统，再核验 SSH','学会区分旧教程环境与当前练习环境。',
 ['SSH','用户','退出状态'],
 '发行版、发行版版本、内核版本和软件版本是不同维度。cat /etc/os-release 认识发行版；uname -r 看内核。教程出现 yum 不表示你的系统也有 yum。SSH 首次连接显示主机密钥指纹，需通过可信渠道核对；不要养成直接忽略变化的习惯。',
 'cat /etc/os-release\nuname -r\nssh student@lab.example\n# student：远程用户名；@ 后是主机名；地址为教学占位符。\n# 首次连接前，从可信渠道核对服务器主机密钥指纹。',
 'cat 读取指定文件；/etc/os-release 是发行版信息文件。uname 的 -r 只显示内核发布版本。ssh 连接的是远程账号；本机用户名不自动变成远程用户名。CentOS Linux 7 已结束生命周期，视频中的 CentOS 7.9 仅作历史环境辨认，新练习选择仍受支持的系统。',
 '误区：教程写了某个版本，新机器就必须照装。版本与包源状态需依据官方支持信息重新选择。',
 ['Ubuntu 上没有 yum，合理做法是什么？','先确认发行版，查对应软件包管理文档',['把系统文件名改成 CentOS','盲目复制网上的一键换源脚本'],'不同发行版使用不同软件包与服务配置，先认环境。'],
 ['SSH 提示主机密钥与已保存记录不同，怎么办？','暂停连接，通过可信渠道核验服务器身份与变更原因',['永久关闭主机密钥检查','把登录密码发到网页询问'],'可能是重装或地址复用，也可能有风险，不能直接假定安全。'],
 '迁移示例：接手旧生产系统时先盘点版本和支持状态，制定升级计划；不能把练习环境的安装步骤直接覆盖生产。','linux',[6,7]);
opsAddCase('shell-status','automation','Shell：变量、引号与退出状态','从一条命令进阶到可解释的小脚本。',
 ['Shell','变量','退出状态'],
 '变量给一个值起名字。Bash 中赋值的等号两边不加空格；引用变量通常使用双引号，以保留值中的空格。$? 是上一条命令的退出状态，下一条命令会覆盖它，所以应及时保存。脚本输出一句“成功”并不代表真实操作成功。',
 'log="/tmp/order app.log"\nif grep -F "ERROR" "$log"; then\n  printf "%s\\n" "发现匹配行"\nelse\n  status=$?\n  printf "grep 状态=%s\\n" "$status"\nfi',
 'log 是变量名；双引号使含空格路径保持为一个参数。grep -F 按字面匹配。grep 的 0 表示匹配到，1 表示未匹配，其他非零值可能是错误；所以 else 里不能直接说“业务正常”。printf 只负责输出。',
 '误区：所有非零退出状态都表示“服务器坏了”。解释必须遵循具体工具的语义。',
 ['路径包含空格，如何把它作为一个对象传给 grep？','使用 "$log" 引用变量',['删除路径中的所有空格','把变量名加上 sudo'],'引号保留参数边界，不改变实际文件名。'],
 ['grep 返回 2，下一步是什么？','检查文件可读性和错误输出，区分执行错误与未匹配',['认为没有 ERROR，业务正常','把返回值强行改成 0'],'工具执行失败不能当作业务无异常的证据。'],
 '迁移示例：自动备份脚本要检查备份工具的退出状态、产物和恢复结果，不能只在末尾打印成功。','linux',[46,49,50]);
opsAddCase('shell-loop','automation','Shell：循环检查与定时任务','让重复检查有对象、有超时、有失败记录。',
 ['循环','条件','退出状态'],
 '循环让同一段逻辑依次处理多个对象。for 后的列表明确范围；do 与 done 标记循环体。自动化还需要超时、错误记录与并发约束，避免一个慢请求拖住全部任务。定时任务的工作目录、环境变量和交互终端常不同。',
 'for service in nginx order; do\n  if systemctl is-active "$service"; then\n    printf "%s active\\n" "$service"\n  else\n    printf "%s needs-check\\n" "$service"\n  fi\ndone\n# 示例仅检查 systemd 活动状态，不证明接口和数据库可用。',
 'service 每轮取一个服务名。is-active 查询单元活动状态，不自动重启。定时执行应使用明确路径、执行账号和日志位置；网络探测另设超时。先手动运行同样环境，再加入定时任务。',
 '误区：进程 active 就等于订单功能正常。应用还可能返回 500 或连接了错误数据库。',
 ['脚本手动正常，定时任务找不到命令，先查什么？','检查执行用户、PATH、工作目录与错误日志',['提高执行频率到每秒','循环里加无条件重启'],'自动执行环境与交互环境不同，需明确依赖。'],
 ['服务 active 但页面 500，怎样补足检查？','继续验证接口响应、请求日志和依赖结果',['把 active 当作完整验收','删掉监控中的 500 记录'],'进程层检查与业务层验证需要结合。'],
 '迁移示例：批量巡检十台机器时，为每台记录时间、对象、结果和失败原因；先限制范围试跑。','linux',[19,53]);
opsAddCase('mysql-objects','database','MySQL：实例、数据库、表与连接身份','先知道连到哪里，再查询业务数据。',
 ['数据库实例','主键','schema'],
 '数据库服务是接收连接的程序；MySQL 实例可以管理多个数据库，每个数据库包含表。表按列描述字段、按行保存记录。MySQL 的 schema 通常与 database 同义；DM8 的 schema 与用户及对象命名规则不同，不可直接套用。',
 "SELECT DATABASE(), CURRENT_USER(), @@hostname, @@port;\nSHOW DATABASES;\nSHOW TABLES FROM order_lab;\n-- 示例结果：order_lab / reader@% / db-lab / 3306",
 'DATABASE() 是当前默认数据库，未选择时可能为 NULL；CURRENT_USER() 显示用于权限检查的账户。@@hostname 和 @@port 提供实例线索，还需与连接配置交叉核对。SHOW 的结果也受权限影响，看不到不一定代表对象不存在。',
 '误区：看到 orders 表名，就确认连对了业务库。同名表可存在于不同数据库或实例。',
 ['查不到表，但同事能查到，先比较什么？','连接实例、默认数据库、账号和权限',['立即新建同名空表','复制同事的管理员密码'],'先识别对象范围，避免掩盖连错环境。'],
 ['页面金额字段找不到，怎样继续定位？','沿接口 SQL、库名、表名、列名逐层确认',['只按中文页面标题猜表名','在所有库批量修改金额列'],'页面字段不一定直接等于表列，可能经过计算或聚合。'],
 '迁移示例：在 DM8 中进一步核对当前 schema 和对象所有者，不要把 MySQL 的默认库判断照搬过去。','mysql',[1,2,17]);
opsAddCase('mysql-types','database','MySQL：数据类型、主键与建表','能读懂一张业务表的字段约束。',
 ['主键','数据库实例','事务'],
 '数据类型约定每列能保存什么。金额常用精确的 DECIMAL，并核对小数位与业务单位；二进制浮点数不适合直接承担精确金额等值计算。NOT NULL 限制空值，主键保证唯一标识，约束要与业务规则对应。',
 'CREATE TABLE order_lab.orders (\n  id BIGINT PRIMARY KEY,\n  order_no VARCHAR(32) NOT NULL,\n  amount DECIMAL(10,2) NOT NULL,\n  created_at DATETIME NOT NULL\n);\n-- 阅读示例，不在网页执行建表。',
 '括号列出字段，逗号分隔；DECIMAL(10,2) 最多十位有效十进制数字，其中两位小数。VARCHAR(32) 是文本长度约束；NOT NULL 不等于字符串一定非空。order_no 还未设置唯一约束，不能凭名字假定唯一。',
 '误区：字段叫 order_no 就自动不重复。唯一性来自约束与写入逻辑，需要明确检查。',
 ['这张表示例中哪列已被约束为主键？','id',['order_no','created_at'],'只有 id 明确写了 PRIMARY KEY，不能从名字推断其他约束。'],
 ['需要禁止重复订单号，合理做法是什么？','先核对现有重复与业务规则，再设计唯一约束并评估变更',['直接改列名为 unique_order_no','假定 NOT NULL 就代表唯一'],'空值约束、唯一约束和业务去重是不同问题。'],
 '迁移示例：为已有大表加约束前，检查存量数据、锁影响、变更窗口和回退方案。','mysql',[18,19,20,21,28]);
opsAddCase('mysql-change','database','MySQL：DDL、DML 与事务边界','分清改结构、改数据与可回滚范围。',
 ['事务','主键','数据库实例'],
 'DDL 如 CREATE、ALTER 改对象结构；DML 如 INSERT、UPDATE、DELETE 改行数据。InnoDB 的事务可把一组数据修改放在一起提交或回滚，但 MySQL 许多 DDL 会隐式提交，不能把所有语句都当作可随意 ROLLBACK。',
 "START TRANSACTION;\nSELECT id, status FROM order_lab.orders WHERE id = 42;\nUPDATE order_lab.orders SET status = 'PAID' WHERE id = 42;\n-- 核验影响行数与业务条件，再决定 COMMIT 或 ROLLBACK。\n-- 仅阅读示例；不要对生产直接试运行。",
 'WHERE 限定目标，但只凭有 WHERE 仍不够，要看条件是否准确。事务期间其他会话可能并发修改数据；真实变更还需核对并发控制与锁。提交后不能靠同一事务的 ROLLBACK 撤销。',
 '误区：先运行 ALTER，出问题再 ROLLBACK 就能恢复全部结构。MySQL 的隐式提交边界必须单独核对。',
 ['同事说所有 DDL 都能 ROLLBACK，你怎么判断？','查数据库与具体语句的事务和隐式提交规则',['只看有没有分号','默认所有数据库行为完全相同'],'数据库产品与语句类别影响事务边界。'],
 ['准备修改订单状态，应该先做什么？','确认环境、目标行、业务条件和恢复方案，再按流程变更',['先全表 UPDATE 再筛选','提交后才查询影响范围'],'先限定目标和验证标准，避免扩大变更。'],
 '迁移示例：数据修复和表结构发布采用不同验收与恢复方案，记录影响行数以及实际提交时间。','mysql',[13,23,29,30]);
opsAddCase('mysql-performance','database','MySQL：索引与慢查询证据','先看查询计划和负载，再讨论加索引。',
 ['索引','主键','延迟'],
 '慢查询可能来自扫描过多、锁等待、磁盘、连接数或应用调用方式。EXPLAIN 展示优化器计划，是分析线索；是否更快要在代表性数据与负载下比较。索引增加写入和空间成本，不是越多越好。',
 "EXPLAIN SELECT id FROM order_lab.orders\nWHERE order_no = 'LAB-42';\n-- 教学计划摘录：type=ALL, key=NULL, rows=100000\n-- rows 是估算；本摘录不代表当前真实数据库。",
 'ALL 表示全表扫描这一访问方式，key=NULL 表示此计划没有选择索引。小表全扫不一定是问题；需结合实际行数、过滤比例、执行耗时和锁等待。EXPLAIN ANALYZE 会实际执行查询，使用前要明确影响。',
 '误区：看到 ALL 就无条件建索引，或把 rows 的估算当作实际返回行数。',
 ['计划 rows=100000，意味着返回了十万行吗？','不是，这是计划中的估算扫描规模线索',['是，等于用户看到的结果数','是，等于已经产生十万条订单'],'计划估算与实际扫描、返回记录不同。'],
 ['决定是否加索引前应怎么验证？','结合条件、现有索引、实际耗时与写入成本测试',['给每个字段各加十个索引','先杀掉全部数据库连接'],'优化需要基线、变更和对照验证，避免以读换来不可接受的写入成本。'],
 '迁移示例：接口变慢时同时收集请求时间、SQL、等待事件和计划，不把所有慢请求都归结为缺索引。','mysql',[17]);
opsAddCase('mysql-recovery','database','MySQL：备份、复制与恢复演练','把“有备份文件”变成“能恢复业务”的证据。',
 ['复制','RPO','RTO'],
 '复制把变更传递到其他实例，也可能传播误删。备份保留独立可恢复的时间点；恢复方案还依赖版本、账号、加密密钥和日志链。RPO 描述可接受的数据丢失窗口，RTO 描述恢复时间目标。',
 '教学恢复记录\n02:00 完整备份完成\n02:00–02:15 日志归档可用\n02:16 发生误删\n02:20 开始隔离恢复\n03:05 关键查询与业务验收通过',
 '这组记录只能支持已验证的恢复点和耗时。复制副本若也接收了误删，不能直接当作误删前备份。恢复测试应在隔离环境，核对表数量、关键记录、权限和应用读写，不直接覆盖生产来试。',
 '误区：备库在线就无需备份；备份文件大就证明能用。',
 ['复制把误删同步到了副本，哪个结论正确？','复制不是独立历史备份，需要可恢复时间点',['副本越多就能自动撤销误删','删掉副本日志即可恢复全部数据'],'复制解决部分可用性需求，不保证保留误删前数据。'],
 ['如何证明备份方案可用？','在隔离环境恢复并验收数据、依赖、恢复点和耗时',['只检查文件扩展名','把备份文件复制两份就宣布验收'],'恢复演练验证能否满足业务的 RPO 和 RTO。'],
 '迁移示例：DM8 也需要对应产品的备份与恢复方法；不能把 MySQL 备份文件直接交给 DM8 恢复。','linux',[50,60]);
opsAddCase('docker-model','container','Docker：镜像、容器与虚拟机','先建立对象关系，再学习容器命令。',
 ['镜像','虚拟机','数据卷'],
 '镜像像应用运行所需文件和默认配置的模板；容器是由镜像创建的运行实例，有自己的可写层。容器通常共享宿主机内核，虚拟机则运行自己的内核。容器退出不一定是安装失败，也可能是主进程已结束。',
 '镜像 order-app:lab → 创建容器 order-a\n同一镜像 order-app:lab → 创建容器 order-b\n停止 order-a：不等于删除镜像\n删除 order-a：不能依赖其可写层保留业务数据',
 '仓库用于保存和分发镜像；标签是可变名字，镜像摘要用于标识具体内容。生产回退要能定位原版本。数据需根据场景放在卷、绑定挂载或外部服务，并有备份方案。',
 '误区：容器就是一台完整虚拟机，删掉重建后所有临时修改都应该还在。',
 ['两个容器来自同一镜像，是否必然共用可写层？','不是，容器各自有可写层',['是，修改会自动互相覆盖','是，和镜像标签相同就共享全部数据'],'共享镜像层不等于共享容器可写层。'],
 ['发布回退时应记录什么？','可定位的镜像版本或摘要，以及配置和数据兼容性',['只记住 latest 这个名字','只保留一个容器截图'],'镜像版本、运行配置和数据状态共同影响回退。'],
 '迁移示例：容器启动正常但读到旧配置，分别核对镜像内容、启动环境与实际挂载路径。','docker',[7,8,13,14]);
opsAddCase('docker-observe','container','Docker：状态、日志与退出原因','从容器状态取得证据，而不是反复重启。',
 ['镜像','退出状态','延迟'],
 'docker ps 默认主要列运行中的容器；-a 包含已停止对象。logs 读取容器日志驱动可提供的标准输出和错误输出，不保证应用写在文件中的日志也能在这里看到。inspect 读取配置与状态，输出可能含敏感环境变量，分享前需脱敏。',
 'docker ps -a\ndocker logs --tail 50 order-lab\ndocker inspect order-lab\n# 教学摘录：State.Status=exited; ExitCode=1\n# 应用日志：config file /app/config.yml not found',
 'ps 的 -a 包括停止对象；--tail 50 限制读取末尾行数；order-lab 是容器名，不是镜像名。ExitCode=1 单独不能说明全部原因，结合日志中的缺失配置再核对挂载与启动参数。',
 '误区：docker ps 没有看到容器，就表示镜像从没下载；退出码 1 就必须删库重装。',
 ['ps 默认列表没有 order-lab，先做什么？','用 ps -a 查看是否已退出',['立即删除所有镜像','认为容器名就是服务器主机名'],'先扩大状态观察范围，不先破坏对象。'],
 ['日志提示配置不存在，优先检查什么？','配置文件、挂载目标和启动参数是否一致',['连续重启十次','关闭全部网络规则'],'具体报错应引导具体核验动作。'],
 '迁移示例：日志为空时检查应用是否写文件、日志驱动和时间范围，不把“没输出”当作“没有错误”。','docker',[20,21,24,26]);
opsAddCase('docker-storage','container','Docker：数据卷、绑定挂载与路径覆盖','解释为什么“文件还在，容器却看不到”。',
 ['数据卷','镜像','目录'],
 '绑定挂载把宿主机路径映射到容器路径；卷由 Docker 管理。挂载到镜像里已有文件的目录时，容器视图中原文件会被挂载内容遮住，并不表示镜像文件被删除。宿主机路径、容器路径和读写权限需要分开检查。',
 '阅读用启动参数：\n--mount type=bind,src=/srv/order/config,dst=/app/config,readonly\n宿主机 /srv/order/config/app.yml\n        ↓ 映射后\n容器   /app/config/app.yml',
 'type=bind 选择绑定挂载；src 是宿主机来源；dst 是容器内目标；readonly 使该挂载只读。它不负责创造正确配置，也不保证运行用户有读取权限。卷可能独立于容器存在，但删除卷依然可能丢数据。',
 '误区：删除容器永远不会影响数据，或把 /app/config 当作宿主机目录。',
 ['挂载空目录后，原配置看不到了，为什么？','挂载遮住了目标目录原内容',['镜像自动把全部文件永久删除','Docker 自动生成了正确配置'],'挂载改变看到的目录内容，应核对来源目录。'],
 ['容器要重建，如何处理重要数据？','确认持久化位置、备份与恢复，再重建并验收',['只保存容器名字','直接加自动删除参数即可'],'持久化、备份、恢复分别解决不同问题。'],
 '迁移示例：数据库容器也要核对数据目录、文件权限和一致性备份，不能只备份 Dockerfile。','docker',[28,32,33]);
opsAddCase('docker-network','container','Docker：端口映射与容器网络','分清访问的是宿主机端口还是容器端口。',
 ['NAT','镜像','网关'],
 '容器有自己的网络视图。容器内的 localhost 通常指容器自己，不能当作另一个数据库容器。发布端口建立宿主机入口与容器端口的对应；同一用户定义网络上的服务也可通过名称通信。',
 '阅读用参数：-p 127.0.0.1:8080:80\n宿主机 127.0.0.1:8080 → 容器 :80\n应用容器 → 同网络 db:3306\n应用容器 → localhost:3306：通常在找自己',
 '-p 后依次是可选宿主机地址、宿主机端口、容器端口。这里绑定回环地址，仅本机入口；不代表公网开放。端口发布、宿主机防火墙、云安全组和应用监听地址要分别核对。',
 '误区：把数据库地址写成 localhost 就能自动找到另一个容器；发布端口就必然全球可访问。',
 ['-p 127.0.0.1:8080:80 中浏览器本机访问哪个端口？','8080',['80 必然是宿主机入口','3306'],'左侧是宿主机入口，右侧是容器服务端口。'],
 ['应用容器连接数据库 localhost 失败，先查什么？','核对数据库服务名、共享网络与真实监听地址',['把所有容器都提权','改成随机公网 IP'],'先识别网络命名空间和连接目标。'],
 '迁移示例：换到云主机也要逐层核验应用监听、映射、系统规则与云入口，不通过一次 ping 判断业务。','docker',[30,31]);
opsAddCase('docker-compose','container','Dockerfile 与 Compose：构建和运行分开看','读懂应用打包与多服务配置的职责。',
 ['Compose','镜像','YAML'],
 'Dockerfile 描述镜像构建步骤，Compose 描述运行多个服务所需的镜像、环境、网络和卷。构建时写进镜像的密码会留在产物或历史中，运行时凭据也需要合适的秘密管理方式。启动顺序不等于应用已能接受请求。',
 'services:\n  web:\n    image: order-app:lab\n    ports:\n      - "127.0.0.1:8080:8080"\n    environment:\n      DB_HOST: db\n  db:\n    image: mysql:8.4\n# 结构阅读片段；缺少凭据、数据卷和健康检查，不是可直接部署的完整文件。',
 'services 下每个键是服务名。image 指定镜像引用；ports 是端口映射列表；environment 给进程配置。YAML 的缩进表达层级。生产还要固定可验证版本、资源、持久化和健康检查；不要把片段当作完整方案。',
 '误区：Compose 文件能解析，业务就一定连得上数据库。语法正确与依赖就绪是两件事。',
 ['负责描述“如何构建镜像”的通常是哪一个？','Dockerfile',['容器运行日志','SSH 主机指纹'],'Dockerfile 定义构建；Compose 定义多服务运行关系。'],
 ['容器都已启动但数据库未就绪，应该补什么？','健康检查、合理重试与业务验收',['仅把服务名字改短','在镜像内硬编码生产密码'],'进程启动、依赖就绪和业务成功需分别验证。'],
 '迁移示例：升级应用时同时检查 Compose 配置、镜像版本、数据库兼容性和回退后的业务结果。','docker',[11]);
opsAddCase('k8s-model','cluster','Kubernetes：控制面、节点与期望状态','理解集群为什么会自动重建 Pod。',
 ['Pod','Deployment','镜像'],
 '控制面接收资源声明、调度并协调实际状态；工作节点运行 Pod。API Server 是资源操作入口，etcd 保存集群状态，调度器选择节点，控制器持续协调，节点上的 kubelet 管理本机 Pod 的运行。容器运行时负责运行容器，Docker Engine 不是唯一选择。',
 '用户声明 Deployment 副本数 2\n→ API Server 接收对象\n→ 控制器协调 ReplicaSet / Pod\n→ 调度器选节点\n→ kubelet 调用容器运行时\n→ 实际就绪状态反馈',
 '声明副本数不意味着立即存在两个健康实例。镜像、资源、网络、探针等条件都会影响结果。手动删除被 Deployment 管理的一个 Pod 后，控制器通常会补建，这是协调期望状态的行为。',
 '误区：Pod 被重建就是系统故障；或以为 Kubernetes 自己包含所有应用数据备份。',
 ['删除一个受 Deployment 管理的 Pod 后又出现新 Pod，原因是什么？','控制器在协调期望副本数',['浏览器缓存制造了一个容器','镜像标签自动创建数据库备份'],'需要区分资源控制关系和一次性对象。'],
 ['两个期望副本只有一个就绪，先查什么？','查 Pod 状态、事件与调度或启动失败原因',['直接改 etcd 内部数据','认为声明 2 就一定已成功'],'从资源状态和事件收集证据，再检查具体失败环节。'],
 '迁移示例：节点故障后应用是否恢复，取决于副本、调度、存储和依赖，而不是“用了集群”就自动高可用。','k8s',[1,2,4,5]);
opsAddCase('k8s-versions','cluster','Kubernetes：版本、运行时与练习集群','不把旧版本搭建步骤当成通用安装脚本。',
 ['CNI','CoreDNS','Pod'],
 '集群安装需要匹配控制面、节点、kubectl、容器运行时与网络插件。视频目录包含 1.23 和 1.28.12 的搭建段落，可用于认识流程，但新环境必须核对当前支持政策、插件兼容与系统前提。不要直接把“关闭所有防护”当作环境初始化。',
 '搭建前核对表\n系统与内核 → 仍受支持\n运行时 → 满足 CRI 与目标版本要求\n网络 → 节点可达、Pod/Service 网段不冲突\n组件 → 版本兼容、镜像可获取\n验证 → 节点、DNS、跨节点通信与样例服务',
 'CNI 提供 Pod 网络接入；CoreDNS 处理集群名称解析。先用隔离的单机练习环境认识对象，再按官方文档准备多节点实验。kubectl 客户端和服务端也有版本偏差限制，具体以官方政策为准。',
 '误区：教程的版本号写死就永远安全；能运行 kubectl version 就证明网络和 DNS 全部通过。',
 ['目录写 kubeadm 1.28.12，新装时应该怎么做？','查当前支持与兼容政策，再选配套版本',['默认这个版本永久受支持','混装任意最新组件'],'版本匹配需要依据当前官方支持信息。'],
 ['搭建后怎样验收？','检查节点、DNS、Pod 网络和样例服务，并记录证据',['只看安装命令退出为 0','只看控制台配色是否正确'],'安装完成与可用集群之间还有运行验证。'],
 '迁移示例：生产升级应先在测试集群验证升级顺序、插件和工作负载，不把实验的重装当作回退。','k8s',[6,7,12,19,20]);
opsAddCase('k8s-scope','cluster','kubectl：上下文、命名空间与只读观察','执行命令前确认自己在看哪个集群。',
 ['命名空间','Pod','Deployment'],
 'kubectl 使用 kubeconfig 中的上下文选择集群、用户和默认命名空间。相同 Pod 名可以出现在不同命名空间；命名空间正确也不能证明集群正确。先读当前上下文，再明确 -n 指定范围，不把正式环境当练习。',
 'kubectl config current-context\nkubectl get namespaces\nkubectl get pods -n order-lab\nkubectl describe pod order-abc -n order-lab\n# 教学摘录：Waiting / ImagePullBackOff\n# Events: Failed to pull image order-app:missing',
 '-n 后是命名空间；get 列对象，describe 汇总状态和事件。ImagePullBackOff 表示镜像拉取反复失败后退避，不表示数据库一定故障。先核对镜像名、版本、凭据与仓库连通性。describe 输出也需要脱敏后再分享。',
 '误区：在默认命名空间查不到就表示整个集群没有该服务；镜像拉取失败只要重启数据库。',
 ['default 查不到 order Pod，先确认什么？','上下文和目标命名空间',['立即重建整个集群','把所有命名空间删除'],'查询范围错误会产生“对象不存在”的假象。'],
 ['ImagePullBackOff 且事件提示标签不存在，先做什么？','核对仓库中的镜像引用与拉取配置',['把副本数加到一百','清空数据库'],'具体事件为下一步检查提供直接线索。'],
 '迁移示例：每次操作前记录集群、命名空间、资源名和操作类型；只读查询也先避免看错环境。','k8s',[16,24,25]);
opsAddCase('k8s-deployment','cluster','Deployment：标签、副本与就绪状态','读懂资源清单中的对象关系。',
 ['Deployment','Pod','就绪探针'],
 'Deployment 的 selector 选中自己管理的 Pod，template 定义新 Pod 的标签和容器。selector 与模板标签应匹配。replicas 是期望数量，READY 是就绪证据；可用性还取决于探针和业务依赖。存活、就绪、启动探针各有职责，不能互换。',
 'apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: order\nspec:\n  replicas: 2\n  selector:\n    matchLabels:\n      app: order\n  template:\n    metadata:\n      labels:\n        app: order\n# 关系片段，省略 template.spec.containers，不能直接 apply。',
 'kind 表示对象类型；replicas: 2 不是立即成功的断言。matchLabels 与模板 labels 对应，写错会破坏对象关系。完整配置还需容器、镜像、资源与探针。先读结构，再按固定版本的完整清单在实验环境验证。',
 '误区：Running 就等于 READY，或增加副本可以修复所有应用配置错误。',
 ['selector 是 app: order，模板却是 app: shop，哪里有问题？','选择器与模板标签不匹配',['副本数必须永远是 1','metadata.name 不能有字母'],'标签连接控制器与 Pod，不能把两端当装饰文字。'],
 ['Pod Running 但未就绪，先查什么？','探针结果、应用日志与依赖状态',['只看 Running 就结束验收','删除所有 Service'],'进程存在与可以接流量是不同状态。'],
 '迁移示例：滚动发布中观察可用副本、错误率和业务请求；旧版本删除前先确认新版本确实就绪。','k8s',[24,26,27]);
opsAddCase('k8s-service','cluster','Service：选择器、端口与无后端','沿稳定入口追到真正处理请求的 Pod。',
 ['Service','Pod','CoreDNS'],
 'Service 通常通过 selector 选择一组 Pod，port 是服务入口，targetPort 是后端目标端口。ClusterIP 主要是集群内部入口；NodePort 和 LoadBalancer 增加不同的暴露方式，但仍要核验网络与访问规则。',
 'kind: Service\nmetadata:\n  name: order\nspec:\n  selector:\n    app: order\n  ports:\n    - port: 80\n      targetPort: 8080\n# 教学摘录：Service 存在；EndpointSlice 中无可用就绪后端。',
 '先比 Service selector 与 Pod 标签，再看就绪状态以及 EndpointSlice；然后核对 targetPort 与应用监听。DNS 能把名称解析成入口地址，不证明后端可用。本片段缺少 apiVersion 等字段，只用于拆解关系。',
 '误区：Service 有地址就一定有健康后端，或把 port: 80 当作容器必然监听 80。',
 ['服务 port=80、targetPort=8080，后端目标端口是哪一个？','8080',['80 必然是容器端口','443'],'服务入口与目标端口可以不同。'],
 ['名称解析正常但没有就绪后端，先查什么？','选择器、Pod 标签、就绪条件和目标端口',['不断刷新 DNS 缓存就够了','把所有 Pod 的 IP 写进用户浏览器'],'把解析、选中后端和应用响应逐层区分。'],
 '迁移示例：页面 502 可沿入口代理 → Service → EndpointSlice → Pod 监听与日志检查，记录每层证据。','k8s',[29,30,31]);
opsAddCase('ansible-scope','automation','Ansible：清单、模块与最小试跑','把批量操作变成可检查、可限制的流程。',
 ['Ansible','SSH','幂等'],
 'inventory 是目标主机清单；模块执行具体任务；playbook 用 YAML 组织任务与目标。Ansible 的 ping 模块通常检查连接与执行环境，不是 ICMP ping，也不证明业务接口健康。先限定一台实验目标，再推广。',
 'ansible lab -m ansible.builtin.ping --limit lab01\n# lab：清单中的组名\n# -m：后接模块名；--limit：进一步限制目标\n# 模块返回 pong：连接和模块执行成功，不等于业务通过。',
 '清单应使用核对过的地址与账号。部分模块能描述目标状态，有助于幂等；直接 shell 执行任意命令不自动幂等。check 模式可辅助预览，但支持程度取决于模块，不能替代测试与结果验证。',
 '误区：ping 成功等于全部服务正常；批量 shell 只要加一次确认就没有风险。',
 ['Ansible ping 返回 pong 可以证明什么？','连接与该模块执行成功',['数据库所有查询都正确','全部防火墙策略都合规'],'模块检查范围有限，业务需要单独验收。'],
 ['准备把配置推到二十台机器，应先怎么做？','核对清单与权限，限制一台试跑并验证差异和回退',['直接全量执行再看结果','关闭所有主机身份检查'],'限制范围降低错误扩散，并让验证更清楚。'],
 '迁移示例：巡检与配置变更使用不同权限、审查和回退标准，不把只读清单直接升级为批量写入。','linux',[37,41,42],'ansible');
opsAddCase('ansible-state','automation','Ansible：期望状态与重复执行','理解为什么模块通常优于拼接管理命令。',
 ['幂等','YAML','Ansible'],
 '任务描述“某个配置应该是什么状态”，比“每次追加一行”更容易重复执行。changed 表示模块报告做了变更，ok 常表示已符合目标，但仍要检查服务行为。通知 handler 也要考虑配置验证和服务影响。',
 '- name: Keep a lab directory present\n  ansible.builtin.file:\n    path: /tmp/order-lab\n    state: directory\n    mode: "0750"\n# 任务片段，不是包含 hosts 的完整 playbook。',
 'name 是说明；file 是模块；path 指定目标；state: directory 描述期望目录；mode 用字符串避免 YAML 数值解释歧义。首次创建与再次执行的结果可能不同，最终仍应读回权限。',
 '误区：每次 echo 追加一行与保证配置行存在完全相同；changed=0 就等于业务必然健康。',
 ['每次执行都追加相同配置行，会出现什么问题？','重复内容累积，不满足期望的幂等效果',['自动变成一次性操作','只要输出绿色就不会重复'],'描述目标状态与反复追加动作不同。'],
 ['任务报告 ok 后怎样验收？','读回目标配置或权限，再验证相关服务行为',['只截取绿色输出','删除执行日志'],'模块报告是证据之一，业务结果仍需验证。'],
 '迁移示例：再次运行应检查是否出现意外变更，避免“自动化”不断改坏已符合要求的对象。','linux',[43,44,45],'ansible');
opsAddCase('nfs','service','NFS：共享目录、挂载与依赖','理解远程目录为什么会拖住本机应用。',
 ['目录','挂载点','用户组'],
 'NFS 把服务器导出的目录挂到客户端目录树中。客户端看到的目录可能依赖远程主机和网络，并不都在本机磁盘。权限还与服务端导出策略、身份映射和文件权限有关。挂载成功不意味着应用账号可写。',
 '服务端导出 /srv/share\n客户端挂载点 /mnt/share\n业务配置读取 /mnt/share/config.yml\n# 阅读链路：应用 → 客户端挂载 → 网络 → NFS 服务 → 服务端文件权限',
 '挂载点是接入另一文件系统的位置。排查应用等待时，要核对目标路径实际属于哪一挂载、远程可达性和服务端状态。不要先把应用运行用户改成 root，也不要把删除挂载目录当成安全卸载。',
 '误区：路径以 / 开头就一定是本机硬盘；root 一定能绕过所有 NFS 服务端策略。',
 ['应用读取 /mnt/share 卡住，首先要识别什么？','这个路径的挂载来源和依赖',['文件名是否足够短','浏览器字号'],'目录路径背后可能有远程依赖。'],
 ['挂载成功但业务账号无权限，怎么继续？','核对实际身份、服务端导出规则与文件权限',['把全系统目录改成 777','删除共享目录重建'],'网络接入与文件授权是不同层面。'],
 '迁移示例：发布前把共享目录的可达性、权限和恢复策略列入依赖检查，避免只验收本机服务。','linux',[20,62,63]);
opsAddCase('zabbix','monitor','监控：指标、触发器与通知链','知道告警为什么没有到达。',
 ['触发器','延迟','退出状态'],
 '以 Zabbix 为例，主机代表监控对象，监控项采集指标，触发器依据表达式判定问题，动作与媒介负责通知。采不到数据、条件没触发、动作不匹配和通知发送失败，是不同故障位置。监控本身也需要被观测。',
 '教学告警链\n监控项：HTTP 错误率 12%\n触发条件：连续 5 分钟 > 5%\n事件：PROBLEM 已产生\n动作：匹配值班组\n通知：邮件发送失败（认证错误）',
 '此快照说明异常已检测，失败在通知发送阶段。应检查媒介配置、接收人、认证与发送日志，而不是把阈值调到永不触发。真实阈值需结合流量规模、持续时间和业务目标。',
 '误区：没人收到消息就一定没有故障；阈值越敏感越好。',
 ['事件已产生但邮件认证失败，先查哪一层？','通知媒介与发送日志',['SQL 字段长度','删除触发器'],'按链路定位，避免改错位置。'],
 ['怎样验收一条新告警？','在受控环境触发、收到通知、处理并验证恢复通知',['只保存表达式','只看监控首页能打开'],'告警验收要覆盖检测、通知与恢复全链路。'],
 '迁移示例：除 CPU 外补充业务错误率、延迟与依赖状态；CPU 低不能证明页面正常。','linux',[73,79,82,83],'zabbix');
opsAddCase('jumpserver','monitor','访问管理：堡垒机、资产与授权','把“能看到资产”与“有权操作”分开。',
 ['堡垒机','SSH','用户组'],
 '堡垒机集中管理身份、资产、授权和会话审计。登记一台主机不等于所有用户有访问权；给访问权也不等于目标账号具有 root 权限。资产地址、协议、目标账号和授权期限都应明确。',
 '用户：值班人员\n资产：order-lab / SSH\n目标账号：ops-reader\n授权：仅指定资产，限定期限\n审计：会话与操作记录\n业务权限：由目标系统与账号另行控制',
 '审计需要保护记录完整性和敏感信息。高危命令过滤只是辅助，不能当成覆盖所有变体的权限控制。文件传输、数据库访问和远程桌面有各自策略，不能从 SSH 授权自动推断。',
 '误区：进了堡垒机就能任意访问所有机器，或命令过滤能替代最小权限。',
 ['资产已登记但用户不能连接，先核对什么？','授权对象、有效期、协议与目标账号',['把所有用户改成管理员','删除审计记录'],'资产管理、访问授权和目标权限分别核验。'],
 ['临时协作需要访问一台主机，怎样授权？','限定资产、账号、期限和所需操作，并保留审计',['共享永久 root 密码','给整个公司网段永久全权'],'授权与任务范围对应，并在结束后回收。'],
 '迁移示例：数据库只读排查使用独立只读账号，不因通过堡垒机连接就扩大到写入权限。','linux',[85,88,91,92],'jumpserver');
opsAddCase('release','incident','综合验收：从发布记录到业务请求','把安装成功、服务运行与业务成功连起来。',
 ['Deployment','延迟','恢复演练'],
 '一次发布包含代码或镜像、配置、数据库结构、静态资源和依赖变更。状态正常只是局部证据。验收需要关联版本、入口请求、日志、数据结果和监控；回退也要考虑数据库向后兼容，不能只恢复一个镜像。',
 '教学发布证据\n镜像：order-app:lab-v2\nPod：2/2 Ready\n入口：GET /api/orders → 500，rid=r-205\n应用：rid=r-205 unknown column payment_type\n数据库：目标库尚未具备该列',
 'Pod 就绪与接口 500 可以同时出现。请求标识把入口错误与应用日志关联，列不存在提示版本与数据库结构可能不匹配；先核对环境与迁移状态，不立刻在生产随手新增列。',
 '误区：两个 Pod Ready 就结束发布；回退镜像一定恢复所有数据。',
 ['本例业务验收是否通过？','没有，接口仍失败并有对应 SQL 错误',['通过，因为 Pod Ready','通过，因为镜像名有 v2'],'业务结果是验收的一部分，不能用基础状态替代。'],
 ['发现结构不匹配，合理下一步是什么？','核对迁移计划与实际环境，按已准备的发布或回退方案处理',['现场随意改表直到不报错','把 HTTP 500 改显示为 200'],'先确认变更计划、兼容性与影响，保留证据。'],
 '迁移示例：同一流程适用于 systemd、Docker 或 Kubernetes 部署，入口、应用、数据库和监控都要验证。','linux',[64,65]);
Object.assign(beginnerTerms,{
 'API Server':'Kubernetes 资源操作的主要接口。kubectl 等客户端把请求发给它；身份认证、授权及校验通过后才会处理对象。',
 etcd:'保存 Kubernetes 集群状态的键值存储，不是应用业务数据库。集群恢复需要合适的 etcd 备份，但它不会自动备份应用持久卷里的数据。',
 调度器:'为尚未安排节点的 Pod 选择合适节点的组件，会考虑资源需求和调度约束。它不负责实际启动容器。',
 控制器:'持续比较期望状态与实际状态，并尝试让两者一致的程序。例如副本不足时协调创建新的对象。',
 kubelet:'运行在节点上的 Kubernetes 代理，负责按 Pod 规范协调容器运行，并上报状态。',
 ReplicaSet:'维持一组符合标签选择器的 Pod 副本数量的 Kubernetes 对象。Deployment 通常通过它管理副本和更新。',
 CRI:'Kubernetes 与容器运行时沟通的接口规范。选择运行时需要检查它与集群版本的兼容，而不是只看是否安装了 Docker 命令。',
 kubeconfig:'kubectl 等客户端读取的连接配置，包含集群、身份和上下文。可能含敏感凭据，不应公开上传或随意分享。',
 标签:'Kubernetes 资源上的键值标记，例如 app: order。选择器通过它挑选对象；名字相同不表示标签一定相同。',
 selector:'选择器，用标签条件挑选资源。例如 Service 的 app: order 会寻找满足该标签的 Pod。需要两端精确匹配。',
 EndpointSlice:'Kubernetes 保存服务后端地址、端口和条件的资源。常由控制器根据 Service 与 Pod 状态维护，用来核对入口背后有没有可用后端。',
 ClusterIP:'Service 的常见内部入口类型，在集群内提供虚拟地址。不能单凭有这个地址就认为公网能直接访问。',
 NodePort:'通过节点端口提供 Service 入口的类型，仍受节点网络、规则和路由限制，不自动获得公网可达性。',
 LoadBalancer:'请求负载均衡入口的 Service 类型，具体由云平台或相应实现提供。没有可用实现时，外部地址可能一直待分配。',
 存活探针:'判断容器是否需要被重启的检查。错误地把外部依赖故障当作容器死亡，可能导致反复重启。',
 启动探针:'给启动较慢的应用留出初始化检测窗口；成功前会抑制对应容器的存活和就绪检查。',
 Dockerfile:'描述如何构建镜像的文本文件。FROM 选基础镜像，COPY 复制构建上下文文件，RUN 执行构建步骤；它与运行时的 Compose 文件职责不同。',
 绑定挂载:'把宿主机一个明确路径映射进容器的存储方式。源路径由宿主机管理，与 Docker 管理的命名卷不同。',
 标准输出:'程序正常输出的常规通道，文件描述符为 1。终端会显示它，也可以重定向或交给下一条管道命令。',
 标准错误:'程序错误或诊断信息的常规通道，文件描述符为 2。默认管道只传标准输出，不能假定错误信息也已传给下一条命令。',
 DDL:'定义数据库对象结构的一类语句，如 CREATE、ALTER、DROP。MySQL 中许多 DDL 有隐式提交，不能假定能用普通事务回滚。',
 DML:'操作表内记录的一类语句，常见 INSERT、UPDATE、DELETE。SELECT 的分类在不同教材中可能另称 DQL，实际要按具体语句判断行为。',
 InnoDB:'MySQL 的常用存储引擎，提供事务、行级锁和崩溃恢复等能力。它的存在不代表任何 SQL 都能回滚。',
 DECIMAL:'用于精确十进制数的 SQL 数据类型，例如 DECIMAL(10,2)。需要结合范围、精度和业务单位选择，不等同于二进制浮点类型。',
 VARCHAR:'保存可变长度文本的数据类型。长度限制不等于唯一约束，还需关注字符集、排序规则和索引限制。',
 NULL:'数据库中表示缺失或未知值的标记，不等于数字 0 或空字符串。判断空值通常使用 IS NULL，而不是 = NULL。',
 EXPLAIN:'MySQL 用于查看语句执行计划的工具。估算计划不是实际业务结果；EXPLAIN ANALYZE 会执行查询，需注意影响。',
 inventory:'Ansible 的目标清单，用主机、组和变量描述管理对象。开始批量操作前应核对清单解析结果与实际授权范围。',
 playbook:'Ansible 用 YAML 编写的任务编排文件。通常包含目标 hosts、任务 tasks 等；一个任务片段不能直接当作完整剧本。',
 handler:'Ansible 中由任务通知触发、通常用于响应配置变化的任务，例如重新加载服务。应先校验配置，并明确服务影响。'
});
